<?php
require_once dirname(__DIR__) . '/_common.php';$pageTitle='Sesi absensi';$sessions=$pdo->query("SELECT s.*, COUNT(a.id) AS total_dicatat, SUM(a.status='hadir') AS hadir, SUM(a.status='izin') AS izin, SUM(a.status='sakit') AS sakit, SUM(a.status='alpa') AS alpa FROM absensi_sesi s LEFT JOIN absensi a ON a.sesi_id=s.id GROUP BY s.id,s.judul,s.tanggal,s.keterangan,s.dibuat_oleh,s.created_at ORDER BY s.tanggal DESC,s.id DESC")->fetchAll();osis_admin_page_start($pageTitle);
?>
<div class="admin-page-actions"><p>Buat sesi rapat atau pertemuan, lalu catat status anggota yang hadir.</p><div class="actions-inline"><a class="button button-outline" href="<?=osis_e(osis_url('admin/absensi/rekap.php'))?>">Lihat rekap anggota</a><a class="button button-primary" href="<?=osis_e(osis_url('admin/absensi/sesi-tambah.php'))?>">＋ Buat sesi</a></div></div><div class="admin-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Sesi</th><th>Tanggal</th><th>Sudah dicatat</th><th>Hadir</th><th>Izin / sakit</th><th>Alpa</th><th></th></tr></thead><tbody><?php if($sessions):foreach($sessions as $session):?><tr><td><strong><?=osis_e($session['judul'])?></strong><small class="table-subtext"><?=osis_e(mb_strimwidth(strip_tags((string)$session['keterangan']),0,70,'…','UTF-8'))?></small></td><td><?=osis_e(osis_format_date($session['tanggal']))?></td><td><?=(int)$session['total_dicatat']?></td><td><?=(int)$session['hadir']?></td><td><?=(int)$session['izin']+(int)$session['sakit']?></td><td><?=(int)$session['alpa']?></td><td><a class="table-action" href="<?=osis_e(osis_url('admin/absensi/isi.php?id='.(int)$session['id']))?>">Isi absensi ↗</a></td></tr><?php endforeach;else:?><tr><td colspan="7" class="empty-inline">Belum ada sesi absensi.</td></tr><?php endif;?></tbody></table></div></div>
<?php osis_admin_page_end(); ?>
